		if (copy_to_sockptr(optlen, &opt.optlen, sizeof(int)))
			return -EFAULT;
	} else if (ops->getsockopt) {
		if (WARN_ONCE(optval.is_kernel || optlen.is_kernel,
			      "Invalid argument type"))
